ight:900}.invoice-section{height:250px;overflow:auto;background:#f8fafc;border-top:1px solid #cbd5e1}.invoice-head{position:sticky;top:0;z-index:2;display:flex;align-items:center;padding:7px 16px;background:#eef2f7;border-bottom:1px solid #cbd5e1}.invoice-table{width:100%;border-collapse:collapse;font-size:11px}.invoice-table th,.invoice-table td{border:1px solid #cbd5e1;padding:6px 7px;text-align:left}.invoice-table th{background:#dfe7f1;font-size:9px;text-transform:uppercase}.amount{text-align:right!important;white-space:nowrap}.action-link{border:0;background:transparent;color:#1d4ed8;text-decoration:underline;font-weight:900;cursor:pointer;padding:2px 4px}.action-link:focus{outline:2px solid #2563eb;outline-offset:1px}.bill-foot{height:54px;display:flex;align-items:center;padding:7px 16px;background:#f8fafc;gap:10px}.bill-foot .status{font-size:11px;font-weight:900;color:#64748b}.bill-foot .status.ok{color:#047857}.bill-foot .status.error{color:#b91c1c}.foot-actions{margin-left:auto;display:flex;gap:8px}.vbtn{height:36px;border:1px solid #94a3b8;background:#fff;padding:0 14px;font-weight:900}.vbtn:focus{outline:2px solid #047857;outline-offset:1px}.vbtn:disabled{opacity:.45;cursor:not-allowed}.vbtn-primary{background:#08765b;color:#fff;border-color:#08765b}.modal-backdrop{position:fixed;inset:0;z-index:250;background:rgba(15,23,42,.58);display:flex;align-items:center;justify-content:center;padding:16px}.modal-backdrop.hidden{display:none!important}.modal-card{width:min(900px,97vw);max-height:94vh;overflow:auto;background:#fff;border:1px solid #64748b;box-shadow:0 24px 70px rgba(15,23,42,.35)}.modal-head{display:flex;align-items:center;justify-content:space-between;background:#055b46;color:#fff;padding:11px 16px}.modal-input{height:38px;border:1px solid #94a3b8;padding:0 8px;outline:none;width:100%;background:#fff}.modal-input:focus{border-color:#047857;box-shadow:0 0 0 2px #d1fae5}.modal-textarea{min-height:72px;padding:8px}.pay-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.pay-summary>div{border:1px solid #cbd5e1;background:#f8fafc;padding:9px}.pay-summary small{display:block;font-size:9px;font-weight:900;color:#64748b;text-transform:uppercase}.pay-summary b{font-size:14px}.print-card{width:min(1120px,98vw);height:min(92vh,920px);display:flex;flex-direction:column;background:#fff;border:1px solid #64748b}.print-frame{flex:1;width:100%;border:0;background:#d1d5db}.attachment-list a{display:inline-block;margin:2px 4px 2px 0;color:#1d4ed8;text-decoration:underline;font-weight:800}.attachment-preview-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(145px,1fr));gap:8px;margin-top:8px}.attachment-preview-card{position:relative;min-height:84px;border:1px solid #cbd5e1;background:#f8fafc;padding:7px 28px 7px 7px;display:flex;gap:7px;align-items:center;overflow:hidden}.attachment-remove{position:absolute;right:4px;top:4px;width:22px;height:22px;border:1px solid #ef4444;background:#fff;color:#b91c1c;font-size:17px;font-weight:900;line-height:18px;cursor:pointer}.attachment-remove:focus{outline:2px solid #ef4444;outline-offset:1px}.attachment-preview-card img{width:54px;height:54px;object-fit:cover;border:1px solid #cbd5e1;background:#fff}.attachment-preview-icon{width:54px;height:54px;display:flex;align-items:center;justify-content:center;border:1px solid #cbd5e1;background:#fff;font-size:11px;font-weight:900;color:#b91c1c}.attachment-preview-name{font-size:10px;font-weight:800;overflow-wrap:anywhere;line-height:1.25}.empty-area{padding:28px;text-align:center;color:#64748b;font-weight:700}.kbd{border:1px solid #cbd5e1;background:#fff;padding:0 4px;font-size:9px;font-weight:900}
@media(max-width:1100px){.so-summary{grid-template-columns:repeat(3,minmax(0,1fr))}.filter-btn{min-width:210px}}
</style>
