            <label><span class="mb-1 block text-[10px] font-black uppercase text-slate-500">Pending SO</span><button type="button" id="soBtn" class="filter-btn {{ $selectedOrder ? '' : 'empty' }}" data-so-id="{{ $selectedOrder?->id }}" {{ $selectedCustomer ? '' : 'disabled' }}>{{ $selectedOrder?->so_number ?: 'Select SO' }}</button></label>
            <div class="ml-auto text-right"><div id="headerStatus" class="text-[11px] font-black text-emerald-700">Ready</div><button type="button" id="closeBilling" class="mt-1 h-8 w-8 border border-slate-300 bg-white font-black">×</button></div>
