                <thead><tr><th>Select</th><th>Status</th><th>Sr No</th><th>LR No</th><th>LR Date</th><th>Lorry No</th><th>Vehicle Type</th><th>Transport</th><th>Supplier</th><th>Bill No</th><th>Description</th></tr></thead>
