                <label class="md:col-span-2"><span class="mb-1 block text-[10px] font-black uppercase text-slate-500">Acknowledgement Attachments <span id="attachmentRequiredMark" class="text-red-700">*</span></span><input id="billAttachments" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" class="modal-input py-1"><span class="mt-1 block text-[10px] font-semibold text-slate-500">Add one attachment at a time. After selecting a file its preview appears below; choose again to append another.</span><div id="existingAttachmentPreview" class="attachment-preview-grid"></div><div id="newAttachmentPreview" class="attachment-preview-grid"></div></label>
                <label class="md:col-span-2"><span class="mb-1 block text-[10px] font-black uppercase text-slate-500">Remarks</span><textarea id="billRemarks" name="remarks" class="modal-input modal-textarea"></textarea></label>
