@push('scripts')
<script>
document.addEventListener('DOMContentLoaded',()=>{
    const csrf=document.querySelector('meta[name="csrf-token"]').content;
    const routes={data:@json(route('sale.billing.data')),soOptions:@json(route('sale.billing.so-options')),store:@json(route('sale.billing.store')),base:@json(url('/sale/bills'))};
    const customerBtn=document.getElementById('customerBtn'),soBtn=document.getElementById('soBtn'),tripBody=document.getElementById('tripBody'),invoiceBody=document.getElementById('invoiceBody'),tripWrap=document.getElementById('tripWrap');
    const footerStatus=document.getElementById('footerStatus'),headerStatus=document.getElementById('headerStatus'),checkAllBtn=document.getElementById('checkAllBtn'),createBillBtn=document.getElementById('createBillBtn');
    const initialEditId=Number(new URL(window.location.href).searchParams.get('edit_invoice_id'))||null;
    let state={customerId:Number(customerBtn.dataset.customerId)||null,customerName:customerBtn.textContent.trim(),soId:Number(soBtn.dataset.soId)||null,order:null,trips:[],invoices:[],selected:new Set(),tripOpener:null,printOpener:null,editingInvoiceId:initialEditId,editingInvoice:null};
    const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
    const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
    const today=()=>{const d=new Date(),o=d.getTimezoneOffset();return new Date(d.getTime()-o*60000).toISOString().slice(0,10)};
    const setStatus=(msg,type='')=>{footerStatus.textContent=msg;footerStatus.className='status '+type;headerStatus.textContent=msg;headerStatus.className='text-[11px] font-black '+(type==='error'?'text-red-700':'text-emerald-700')};
    function syncButtons(){const edit=!!state.editingInvoiceId;checkAllBtn.disabled=edit;createBillBtn.innerHTML=edit?'Edit Bill <span class="kbd">Ctrl+B</span>':'Create Bill <span class="kbd">Ctrl+B</span>';}
    const updateUrl=()=>{const u=new URL(window.location.href);state.customerId?u.searchParams.set('customer_id',state.customerId):u.searchParams.delete('customer_id');state.soId?u.searchParams.set('sales_order_id',state.soId):u.searchParams.delete('sales_order_id');state.editingInvoiceId?u.searchParams.set('edit_invoice_id',state.editingInvoiceId):u.searchParams.delete('edit_invoice_id');history.replaceState({},'',u.pathname+u.search)};
    function clearEdit(){state.editingInvoiceId=null;state.editingInvoice=null;syncButtons();}

    function openCustomer(search=''){
        window.MasterSelector.open({type:'customers',title:'Select Customer',search,opener:customerBtn,onSelect:item=>{clearEdit();state.customerId=Number(item.id);state.customerName=item.name;state.soId=null;state.order=null;state.selected.clear();customerBtn.dataset.customerId=item.id;customerBtn.textContent=item.name;customerBtn.classList.remove('empty');soBtn.dataset.soId='';soBtn.textContent='Select SO';soBtn.classList.add('empty');soBtn.disabled=false;updateUrl();loadData(false).then(()=>setTimeout(()=>soBtn.focus(),20));}});
    }
    function openSO(search=''){
        if(!state.customerId){setStatus('Select Customer first.','error');window.AppToast?.('Select Customer first.','error');customerBtn.focus();return;}
        const url=routes.soOptions+'?customer_id='+encodeURIComponent(state.customerId);
        window.MasterSelector.open({url,title:'Select Pending SO',search,opener:soBtn,onSelect:item=>{clearEdit();state.soId=Number(item.id);state.selected.clear();soBtn.dataset.soId=item.id;soBtn.textContent=item.so_number||item.name;soBtn.classList.remove('empty');updateUrl();loadData(true);}});
    }
    customerBtn.addEventListener('click',()=>openCustomer());soBtn.addEventListener('click',()=>openSO());
    [customerBtn,soBtn].forEach(btn=>btn.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();btn===customerBtn?openCustomer():openSO();}else if(e.key==='Backspace'){e.preventDefault();clearEdit();if(btn===customerBtn){state.customerId=null;state.customerName='';state.soId=null;customerBtn.textContent='Select Customer';customerBtn.classList.add('empty');soBtn.textContent='Select SO';soBtn.classList.add('empty');soBtn.disabled=true;}else{state.soId=null;soBtn.textContent='Select SO';soBtn.classList.add('empty');}state.selected.clear();updateUrl();loadData(false);}}));

    async function loadData(focusTrips=false){
        const u=new URL(routes.data,window.location.origin);if(state.customerId)u.searchParams.set('customer_id',state.customerId);if(state.soId)u.searchParams.set('sales_order_id',state.soId);if(state.editingInvoiceId)u.searchParams.set('edit_invoice_id',state.editingInvoiceId);
        try{setStatus('Loading...');const r=await fetch(u,{headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to load billing data');
            if(d.customer){state.customerId=Number(d.customer.id);state.customerName=d.customer.name;customerBtn.dataset.customerId=d.customer.id;customerBtn.textContent=d.customer.name;customerBtn.classList.remove('empty');soBtn.disabled=false;}
            state.order=d.order;state.trips=d.trips||[];state.invoices=d.invoices||[];state.editingInvoice=d.editing_invoice||null;if(state.order){state.soId=Number(state.order.id);soBtn.dataset.soId=state.order.id;soBtn.textContent=state.order.so_number;soBtn.classList.remove('empty');}
            state.selected=new Set([...state.selected].filter(id=>state.trips.some(t=>t.id===id&&!t.billed)));renderAll();syncButtons();updateUrl();setStatus(state.editingInvoice?`Editing ${state.editingInvoice.bill_no} · ${state.trips.length} trip(s) loaded`:state.order?`${state.order.pending_count} truck(s) pending billing`:'Ready','ok');if(focusTrips)setTimeout(()=>focusFirstPending(),20);
        }catch(err){setStatus(err.message||'Unable to load','error');window.AppToast?.(err.message||'Unable to load billing data.','error');}
    }
    function renderAll(){renderSummary();renderTrips();renderInvoices();updateSelectionStatus();}
    function renderSummary(){const box=document.getElementById('soSummary');if(!state.order){box.classList.add('hidden');return;}box.classList.remove('hidden');document.getElementById('sumSo').textContent=state.order.so_number;document.getElementById('sumRoute').textContent=`${state.order.from_location} → ${state.order.to_location}`;document.getElementById('sumDescription').textContent=state.order.description||'-';document.getElementById('sumRate').textContent=money(state.order.per_trip_cost);document.getElementById('sumTrips').textContent=`${state.order.billed_count} billed / ${state.order.voucher_count} sent / ${state.order.trips_quantity} ordered`;document.getElementById('sumPending').textContent=state.order.pending_count;}
    function renderTrips(){if(!state.order){tripBody.innerHTML='<tr><td colspan="11" class="empty-area">Select Customer and pending SO.</td></tr>';return;}if(!state.trips.length){tripBody.innerHTML='<tr><td colspan="11" class="empty-area">No voucher/truck entries found.</td></tr>';return;}const editing=!!state.editingInvoiceId;tripBody.innerHTML=state.trips.map((t,i)=>`<tr class="${editing?'editing-bill':(t.billed?'billed':'pending')}" data-trip-row="${i}"><td class="text-center">${editing||t.billed?'<span class="status-badge">✓</span>':`<input type="checkbox" class="trip-check" data-trip-check="${t.id}" data-trip-index="${i}" ${state.selected.has(t.id)?'checked':''}>`}</td><td class="status-cell"><span class="status-badge">${editing?'IN BILL':(t.billed?'BILLED':'PENDING')}</span></td><td>${esc(t.sr_no)}</td><td>${esc(t.lr_no||'-')}</td><td>${esc(t.lr_date||'-')}</td><td>${esc(t.lorry_number||'-')}</td><td>${esc(t.vehicle_type||'-')}</td><td>${esc(t.transport_name||'-')}</td><td>${esc(t.supplier||'-')}</td><td>${t.billed?`<button type="button" class="action-link" data-print-invoice="${t.invoice_id}">${esc(t.bill_no)}</button>`:'-'}</td><td>${esc(t.description||'-')}</td></tr>`).join('');}
    function renderInvoices(){if(!state.customerId){invoiceBody.innerHTML='<tr><td colspan="11" class="empty-area">Select a customer to see bills.</td></tr>';return;}if(!state.invoices.length){invoiceBody.innerHTML='<tr><td colspan="11" class="empty-area">No bills generated for this selection.</td></tr>';return;}invoiceBody.innerHTML=state.invoices.map(i=>`<tr><td><b>${esc(i.bill_no)}</b></td><td>${esc(i.invoice_date)}</td><td>${esc(i.so_number||'-')}</td><td>${esc(i.lr_numbers_text||'-')}</td><td>${i.trip_count}</td><td class="amount"><b>${money(i.total_amount)}</b></td><td class="amount">${money(i.paid_amount)}</td><td class="amount" style="color:${i.outstanding>0?'#b91c1c':'#047857'}"><b>${money(i.outstanding)}</b></td><td class="attachment-list">${i.attachments?.length?i.attachments.map(a=>`<a href="${a.url}" target="_blank" rel="noopener">${esc(a.name)}</a>`).join(''):'-'}</td><td><button type="button" class="action-link" data-edit-invoice="${i.id}">Edit</button></td><td><button type="button" class="action-link" data-print-invoice="${i.id}">Print</button></td></tr>`).join('');}
    function pendingChecks(){return Array.from(document.querySelectorAll('[data-trip-check]'));}
    function focusFirstPending(){pendingChecks()[0]?.focus();}
    function focusCheckByPosition(current,delta){const arr=pendingChecks();const i=arr.indexOf(current);arr[Math.max(0,Math.min(arr.length-1,i+delta))]?.focus();}
    tripBody.addEventListener('change',e=>{const c=e.target.closest('[data-trip-check]');if(!c)return;const id=Number(c.dataset.tripCheck);c.checked?state.selected.add(id):state.selected.delete(id);updateSelectionStatus();});
    tripBody.addEventListener('keydown',e=>{const c=e.target.closest('[data-trip-check]');if(!c)return;if(e.key==='Enter'){e.preventDefault();c.checked=!c.checked;c.dispatchEvent(new Event('change',{bubbles:true}));focusCheckByPosition(c,1);}else if(e.key==='ArrowDown'){e.preventDefault();focusCheckByPosition(c,1);}else if(e.key==='ArrowUp'){e.preventDefault();focusCheckByPosition(c,-1);}});
    tripBody.addEventListener('click',e=>{const p=e.target.closest('[data-print-invoice]');if(p)openPrint(Number(p.dataset.printInvoice),p,true);});
    function updateSelectionStatus(){if(state.editingInvoice){footerStatus.textContent=`Editing ${state.editingInvoice.bill_no} · ${state.trips.length} trip(s)`;return;}const c=state.selected.size;const freight=state.order?c*Number(state.order.per_trip_cost||0):0;footerStatus.textContent=c?`${c} truck(s) selected · Default Total ${money(freight)}`:'No trucks selected';}
    function toggleAll(){if(!state.order||state.editingInvoiceId)return;const pending=state.trips.filter(t=>!t.billed).map(t=>t.id);const all=pending.length&&pending.every(id=>state.selected.has(id));state.selected=new Set(all?[]:pending);renderTrips();updateSelectionStatus();if(!all)focusFirstPending();}
    checkAllBtn.addEventListener('click',toggleAll);

    const billModal=document.getElementById('billModal'),billForm=document.getElementById('billForm'),invoiceDate=document.getElementById('invoiceDate'),totalInput=document.getElementById('billTotalAmount'),attachInput=document.getElementById('billAttachments'),remarksInput=document.getElementById('billRemarks'),billSubmit=document.getElementById('billSubmit');
    const existingPreview=document.getElementById('existingAttachmentPreview'),newPreview=document.getElementById('newAttachmentPreview');
    let pendingFiles=[],removedAttachmentIds=new Set(),pendingObjectUrls=[];
    function clearPendingObjectUrls(){pendingObjectUrls.forEach(url=>URL.revokeObjectURL(url));pendingObjectUrls=[];}
    function previewCard(name,url=null,mime='',removeAttrs=''){const image=(mime||'').startsWith('image/')||/\.(png|jpe?g|webp)$/i.test(name);return `<div class="attachment-preview-card">${image&&url?`<img src="${url}" alt="">`:`<div class="attachment-preview-icon">${/\.pdf$/i.test(name)?'PDF':'FILE'}</div>`}<div class="attachment-preview-name">${url?`<a href="${url}" target="_blank" rel="noopener" class="text-blue-700 underline">${esc(name)}</a>`:esc(name)}</div><button type="button" class="attachment-remove" ${removeAttrs} title="Remove attachment" aria-label="Remove attachment">×</button></div>`;}
    function activeExistingAttachments(){return (state.editingInvoice?.attachments||[]).filter(a=>!removedAttachmentIds.has(Number(a.id)));}
    function renderExistingAttachments(){const list=activeExistingAttachments();existingPreview.innerHTML=list.map(a=>previewCard(a.name,a.url,a.mime_type||'',`data-remove-existing="${a.id}"`)).join('');}
    function renderNewAttachments(){clearPendingObjectUrls();newPreview.innerHTML=pendingFiles.map((f,i)=>{const image=(f.type||'').startsWith('image/');if(!image)return previewCard(f.name,null,f.type,`data-remove-pending="${i}"`);const url=URL.createObjectURL(f);pendingObjectUrls.push(url);return previewCard(f.name,url,f.type,`data-remove-pending="${i}"`);}).join('');}
    function resetAttachmentDraft(){pendingFiles=[];removedAttachmentIds=new Set();attachInput.value='';renderExistingAttachments();renderNewAttachments();}
    existingPreview.addEventListener('click',e=>{const b=e.target.closest('[data-remove-existing]');if(!b)return;removedAttachmentIds.add(Number(b.dataset.removeExisting));renderExistingAttachments();attachInput.focus();});
    newPreview.addEventListener('click',e=>{const b=e.target.closest('[data-remove-pending]');if(!b)return;pendingFiles.splice(Number(b.dataset.removePending),1);renderNewAttachments();attachInput.focus();});
    function updateDraft(){const count=state.editingInvoice?Number(state.editingInvoice.trip_count||state.trips.length):state.selected.size;document.getElementById('draftTrips').textContent=count;document.getElementById('draftRate').textContent=money(state.order?.per_trip_cost||0);document.getElementById('draftTotal').textContent=money(Number(totalInput.value||0));}
    function openBill(){const editing=!!state.editingInvoiceId;if(!state.customerId||!state.soId){window.AppToast?.('Select Customer and SO first.','error');return;}if(!editing&&!state.selected.size){window.AppToast?.('Select at least one acknowledged truck.','error');focusFirstPending();return;}if(editing&&!state.editingInvoice){window.AppToast?.('Bill details are still loading.','warning');return;}state.tripOpener=document.activeElement;invoiceDate.value=editing?(state.editingInvoice.invoice_date_raw||today()):today();totalInput.value=editing?Number(state.editingInvoice.customer_freight||state.editingInvoice.total_amount||0).toFixed(2):(state.selected.size*Number(state.order?.per_trip_cost||0)).toFixed(2);remarksInput.value=editing?(state.editingInvoice.remarks||''):'';document.getElementById('billModalTitle').textContent=editing?`Edit ${state.editingInvoice.bill_no}`:'Create Invoice from Acknowledged Trucks';document.getElementById('attachmentRequiredMark').classList.toggle('hidden',editing&&state.editingInvoice.attachments?.length);billSubmit.innerHTML=editing?'Save Changes & Print <span class="kbd">Ctrl+S</span>':'Create Bill & Print <span class="kbd">Ctrl+S</span>';resetAttachmentDraft();updateDraft();billModal.classList.remove('hidden');setTimeout(()=>invoiceDate.focus(),20);}
    function closeBill(){billModal.classList.add('hidden');setTimeout(()=>state.tripOpener?.focus?.()||createBillBtn.focus(),0);}
    createBillBtn.addEventListener('click',openBill);document.getElementById('billClose').addEventListener('click',closeBill);document.getElementById('billCancel').addEventListener('click',closeBill);billModal.addEventListener('mousedown',e=>{if(e.target===billModal)closeBill();});totalInput.addEventListener('input',updateDraft);attachInput.addEventListener('change',()=>{const f=attachInput.files?.[0];if(f){if(pendingFiles.length>=20){window.AppToast?.('Maximum 20 attachments allowed.','warning');}else{pendingFiles.push(f);renderNewAttachments();}attachInput.value='';}});
    billForm.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeBill();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();billForm.requestSubmit();return;}if(e.key!=='Enter'||e.target===remarksInput)return;e.preventDefault();const order=[invoiceDate,totalInput,attachInput,remarksInput,billSubmit],i=order.indexOf(e.target);if(e.target===invoiceDate&&!invoiceDate.value){invoiceDate.showPicker?.();return;}if(i>=0&&i<order.length-1){order[i+1].focus();order[i+1].select?.();}else if(e.target===billSubmit)billForm.requestSubmit();});
    billForm.addEventListener('submit',async e=>{e.preventDefault();const editing=!!state.editingInvoiceId,total=Number(totalInput.value||0);if(total<=0){window.AppToast?.('Enter Total Amount.','error');totalInput.focus();return;}const existingCount=activeExistingAttachments().length;if(!editing&&!pendingFiles.length){window.AppToast?.('Please add at least one acknowledgement attachment.','error');attachInput.focus();return;}if(editing&&!existingCount&&!pendingFiles.length){window.AppToast?.('Please keep or add at least one acknowledgement attachment.','error');attachInput.focus();return;}billSubmit.disabled=true;billSubmit.textContent=editing?'Saving...':'Creating...';const fd=new FormData();fd.append('invoice_date',invoiceDate.value);fd.append('total_amount',totalInput.value);fd.append('remarks',remarksInput.value||'');pendingFiles.forEach(f=>fd.append('attachments[]',f));removedAttachmentIds.forEach(id=>fd.append('remove_attachment_ids[]',id));let url=routes.store;if(editing){url=`${routes.base}/${state.editingInvoiceId}`;fd.append('_method','PUT');}else{fd.append('customer_id',state.customerId);fd.append('sales_order_id',state.soId);[...state.selected].forEach(id=>fd.append('voucher_ids[]',id));}
        try{const r=await fetch(url,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf},body:fd}),d=await r.json();if(!r.ok)throw new Error(d.message||Object.values(d.errors||{})[0]?.[0]||'Unable to save bill');billModal.classList.add('hidden');state.selected.clear();if(editing){await loadData(false);}else{await loadData(false);if(state.order&&Number(state.order.pending_count)===0){state.soId=null;state.order=null;soBtn.dataset.soId='';soBtn.textContent='Select SO';soBtn.classList.add('empty');updateUrl();await loadData(false);}}setStatus(d.message,'ok');window.AppToast?.(d.message||'Bill saved successfully.','success');openPrint(d.invoice.id,createBillBtn,true);}catch(err){window.AppToast?.(err.message||'Unable to save bill.','error',5500);}finally{billSubmit.disabled=false;if(!state.editingInvoiceId)billSubmit.innerHTML='Create Bill & Print <span class="kbd">Ctrl+S</span>';}});

    async function startEdit(id,opener){const inv=state.invoices.find(x=>Number(x.id)===Number(id));if(!inv)return;state.editingInvoiceId=Number(id);state.customerId=Number(inv.customer_id);state.customerName=inv.customer_name||state.customerName;state.soId=Number(inv.sales_order_id);state.selected.clear();customerBtn.dataset.customerId=inv.customer_id;customerBtn.textContent=inv.customer_name||customerBtn.textContent;customerBtn.classList.remove('empty');soBtn.disabled=false;soBtn.dataset.soId=inv.sales_order_id;soBtn.textContent=inv.so_number||'SO';soBtn.classList.remove('empty');updateUrl();await loadData(false);tripWrap.scrollTo({top:0,left:0,behavior:'smooth'});setTimeout(()=>createBillBtn.focus(),80);window.AppToast?.(`${inv.bill_no} loaded above. Review entries and choose Edit Bill.`, 'info', 5000);}
    invoiceBody.addEventListener('click',e=>{const ed=e.target.closest('[data-edit-invoice]');if(ed){startEdit(Number(ed.dataset.editInvoice),ed);return;}const pr=e.target.closest('[data-print-invoice]');if(pr)openPrint(Number(pr.dataset.printInvoice),pr,true);});
    invoiceBody.addEventListener('keydown',e=>{const ed=e.target.closest('[data-edit-invoice]');if(ed&&e.key==='Enter'){e.preventDefault();startEdit(Number(ed.dataset.editInvoice),ed);return;}const pr=e.target.closest('[data-print-invoice]');if(pr&&e.key==='Enter'){e.preventDefault();openPrint(Number(pr.dataset.printInvoice),pr,true);}});

    const printModal=document.getElementById('printModal'),printFrame=document.getElementById('printFrame');let autoPrint=false;
    function openPrint(id,opener,auto=false){state.printOpener=opener;autoPrint=auto;printFrame.src=`${routes.base}/${id}/print?embedded=1`;printModal.classList.remove('hidden');}
    function closePrint(){printModal.classList.add('hidden');printFrame.src='about:blank';autoPrint=false;setTimeout(()=>state.printOpener?.focus?.(),0);}
    printFrame.addEventListener('load',()=>{if(autoPrint&&printFrame.src!=='about:blank'){setTimeout(()=>{try{printFrame.contentWindow.focus();printFrame.contentWindow.print();}catch(e){}},250);autoPrint=false;}});
    document.getElementById('printNow').addEventListener('click',()=>{try{printFrame.contentWindow.focus();printFrame.contentWindow.print();}catch(e){}});document.getElementById('printClose').addEventListener('click',closePrint);printModal.addEventListener('mousedown',e=>{if(e.target===printModal)closePrint();});
    window.addEventListener('message',e=>{if(e.origin===window.location.origin&&e.data?.type==='xyz-invoice-afterprint'&&!printModal.classList.contains('hidden'))closePrint();});

    document.getElementById('closeBilling').addEventListener('click',()=>window.AppPageExit?.('#nav-sale'));
    window.addEventListener('keydown',e=>{if(!printModal.classList.contains('hidden')){if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closePrint();}return;}if(!billModal.classList.contains('hidden')){if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeBill();}return;}if(e.altKey&&e.key.toLowerCase()==='a'){e.preventDefault();toggleAll();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='b'){e.preventDefault();openBill();return;}});

    syncButtons();loadData(false).then(()=>{if(!state.customerId)setTimeout(()=>customerBtn.focus(),30);else if(!state.soId&&!state.editingInvoiceId)setTimeout(()=>soBtn.focus(),30);else if(!state.editingInvoiceId)setTimeout(()=>focusFirstPending(),30);});
});
</script>
@endpush
